const ref={evidenceRefs:[0]};
const eq=(field:string,value:string|number|boolean):Rule=>({op:'eq',field,value});
function base(id:string,title:string,text:string,instruction:string,explanation:string):{source:Source;activity:ActivityBase}{
 const source:Source={id:`benchmark-source-${id}`,title:`Fictional benchmark: ${title}`,text:`Original fictional benchmark specification. Rules apply only to this prepared case.\n\n${text}`,kind:'text',status:'ready',addedAt:'2026-10-10T00:00:00.000Z'};
 return{source,activity:{version:1,id:`benchmark-${id}`,scaffoldIds:[id],title,instruction,explanation,hint:'Consult the explicit conditions and relationships in the supplied specification.',sourceRefs:[{sourceId:source.id,evidence:text}],reviewStatus:'needs-review'}};
}
function add(id:string,b:ReturnType<typeof base>,activity:StructuredActivity,prerequisiteEvidence:string[],correctActions?:string[]){fixtures.push({scaffoldId:id,source:b.source,activity,prerequisiteEvidence,lesson:activity.explanation,...(correctActions?{correctActions}:{})});}

